import {NAV_COLLAPSED_KEY} from './unified-layout';

type ApiResult<T>={ok:boolean;data?:T;error?:{message?:string}|string};
type OrderRow={id:string;orderNo:string;phone:string;phoneCanonical?:string|null;customerName:string;updatedAt:string;products:{code:string;quantity:number}[];workflowStatus:string;trackingStatus:string};
type OrderDetail={id:string;orderNo:string;entryState:string;draftRevision:number;orderStatus:string;trackingStatus:string;confirmed:boolean;customerInformationConfirmedAt?:string|null;orderConfirmationConfirmedAt?:string|null;amounts:{orderTotal:number|null};customer:{fullName:string|null;firstName:string|null;lastName:string|null;phone:string|null;email:string|null;country:string|null;province:string|null;city:string|null;street:string|null;residence:string|null};items:{id:string;packageId:string;businessCode:string;productName:string;quantity:number;unitActualPriceFils:number|null}[];packages:{id:string;seriesCode:string;status:string}[];addressVerification:{status:string;reason?:string;checkedAt?:string|null};report:{number:string;rawNumber?:string;reviewedAt?:string|null;readiness:{ok:boolean;checks:{ok:boolean;text:string}[]}}};
type ChatMedia={type?:string;status?:string;source?:string;mimetype?:string|null;filename?:string|null;dataUrl?:string};
type ChatMessage={id:string;direction:string;text:string;sentAt:string;sender?:string;metadata?:{sender?:string;origin?:string;messageType?:string;note?:string|null;media?:ChatMedia[];location?:{description?:string|null}}};
type CustomerSuggestion={id:string;field:string;label:string;current:string;proposed:string;evidence:{id:string;sentAt:string}[];source?:'ai'|'location'};
type Binding={token:string;phone:string;accountId:string;chatId:string;identityVerified?:boolean;messages:ChatMessage[];hasMore?:boolean;historyPartial?:boolean;historySaveIssue?:string;sourceCount?:number};
type AssistantSettingsState={activeProvider:string;providers:Record<string,{model:string;hasApiKey:boolean}>};
type InboxItem={phone:string;chatId:string;name:string;avatarUrl?:string|null;updatedAt:string;preview:string;direction:string;unreadCount:number};
type InboxResult={items:InboxItem[];total:number;offset:number;hasMore:boolean;hiddenChatCount?:number};
type Conversation=InboxItem&{orderIds:string[];latestOrder?:OrderRow};
type DraftAttachment={id:string;name:string;mimetype:string;dataUrl:string;size:number;kind:'image'|'file'};
const normalizePhone=(value:string)=>value.replace(/[^\d]/g,'');
const orderPhoneKey=(order:OrderRow)=>order.phoneCanonical||normalizePhone(order.phone);
const associateOrders=(orders:OrderRow[],items:InboxItem[]):Conversation[]=>{const byPhone=new Map<string,OrderRow[]>();for(const order of orders){const key=orderPhoneKey(order);if(key)byPhone.set(key,[...(byPhone.get(key)||[]),order]);}return items.map(item=>{const related=byPhone.get(normalizePhone(item.phone))||[],latestOrder=[...related].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];return {...item,orderIds:related.map(value=>value.id),latestOrder};});};
const text=(value:unknown)=>String(value??'').trim()||'—';
const money=(value:number|null|undefined)=>value===null||value===undefined?'待核对':`AED ${(value/100).toFixed(2)}`;
const progressLabels:Record<string,string>={draft:'待补齐资料',pending:'等待客户确认',unshipped:'待发货',awaiting_report:'待报单',outbound_processing:'出库中',shipped_pending:'运输中',signed:'已签收',refused:'已拒收',unreachable:'联系不上',cancelled_before_outbound:'已取消',cancelled_after_outbound:'已取消',partial_complete:'部分完成',completed_mixed:'已完成'};
const addressLabels:Record<string,string>={deliverable:'可配送',out_of_range:'超出配送范围',unusable:'地址待补全',failed:'核对失败',not_configured:'待人工核对',pending:'待人工核对'};
const progressLabel=(value:unknown)=>progressLabels[String(value??'')]||'状态待核对';
const addressLabel=(value:unknown)=>addressLabels[String(value??'')]||'待人工核对';
const mediaLabels:Record<string,string>={image:'图片',sticker:'贴纸',gif:'GIF 动图',video:'视频',audio:'语音',ptt:'语音',document:'文件',location:'位置',vcard:'联系人',contact:'联系人',ciphertext:'等待 WhatsApp 解密',album:'媒体相册',unknown:'媒体附件',oversized:'超大媒体',product:'商品卡片',order:'订单卡片',reaction:'表情回应'};
const mediaLabel=(value:unknown)=>mediaLabels[String(value??'')]||'未知类型消息';
const safeLink=(value:string)=>{try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?url.href:null;}catch{return null;}};
const messageLinks=(value:string)=>[...new Set(value.match(/https?:\/\/[^\s<>"']+/g)||[])].map(safeLink).filter((value):value is string=>Boolean(value));
const mapAddressFromLink=(href:string)=>{try{const url=new URL(href),host=url.hostname.toLowerCase(),google=host==='google.com'||host.endsWith('.google.com');if(!google||!url.pathname.startsWith('/maps'))return null;const candidate=url.searchParams.get('q')||url.searchParams.get('query')||url.searchParams.get('destination')||decodeURIComponent(url.pathname.match(/^\/maps\/search\/([^/]+)/)?.[1]||'');const value=candidate.replace(/\+/g,' ').trim();if(!value||value.length>500||/^-?\d{1,2}(?:\.\d+)?\s*,\s*-?\d{1,3}(?:\.\d+)?$/.test(value))return null;return value;}catch{return null;}};
const isSystemMessage=(m:ChatMessage)=>['notification_template','e2e_notification','revoked'].includes(String(m.metadata?.messageType||''));
const isMediaOnlyMessage=(m:ChatMessage)=>Boolean(m.metadata?.media?.length)&&/^\[(?:图片|贴纸|GIF 动图|媒体附件|视频)\]$/.test(m.text.trim());
const systemMessageText=(m:ChatMessage)=>m.metadata?.messageType==='revoked'?'此消息已撤回。':m.metadata?.messageType==='e2e_notification'?'WhatsApp 加密通知。':!m.text.trim()||/^\[(?:未知类型消息|非文字消息[^\]]*)\]$/.test(m.text.trim())?'WhatsApp 系统通知。':m.text;
const safeMediaUrl=(value:unknown)=>typeof value==='string'&&/^data:image\/(?:png|jpeg|webp|gif);base64,[A-Za-z0-9+/]+=*$/.test(value)?value:null;
const safeVideoUrl=(value:unknown)=>typeof value==='string'&&/^data:video\/mp4;base64,[A-Za-z0-9+/]+=*$/.test(value)?value:null;
const messageKey=(value:string)=>value.replace(/^(true|false)_[^_]+_/,'$1_');
const mergeMessages=(current:ChatMessage[],incoming:ChatMessage[])=>{
 const rows=new Map<string,ChatMessage>();
 for(const row of current)rows.set(messageKey(row.id),row);
 for(const row of incoming){const key=messageKey(row.id),previous=rows.get(key),hasCachedImage=previous?.metadata?.media?.some(media=>media.status==='cached'&&Boolean(safeMediaUrl(media.dataUrl)));rows.set(key,hasCachedImage?previous!:row);}
 return [...rows.values()].sort((a,b)=>a.sentAt.localeCompare(b.sentAt)||a.id.localeCompare(b.id));
};

type WorkbenchRequest={request:(value:unknown)=>Promise<{ok:boolean;data?:unknown;error?:string}>};
type WorkbenchBridgeWindow=Window&{manualChat?:WorkbenchRequest;manualReplyTranslation?:WorkbenchRequest};
// The workbench is a controlled srcdoc child of the local dashboard. In the
// packaged app it deliberately has no raw Electron bridge; it may use only the
// same-origin parent's token-bound request facades.
const workbenchHost=():WorkbenchBridgeWindow=>{try{return window.parent!==window&&window.parent.location.origin===window.location.origin?window.parent as WorkbenchBridgeWindow:window as WorkbenchBridgeWindow;}catch{return window as WorkbenchBridgeWindow;}};
function ordersApi<T>(name:string,payload?:unknown){const fn=window.inventoryApp?.orders?.[name]||workbenchHost().inventoryApp?.orders?.[name];if(!fn)return Promise.reject(new Error('订单服务尚未就绪'));return fn(payload).then((result:ApiResult<T>)=>{if(!result.ok)throw new Error(typeof result.error==='string'?result.error:result.error?.message||'订单操作失败');return result.data as T;});}
function chatApi<T>(action:string,payload?:unknown){const api=(window as WorkbenchBridgeWindow).manualChat||workbenchHost().manualChat;if(!api)return Promise.reject(new Error('请在连接与设置完成 WhatsApp 登录'));return api.request({action,payload}).then(result=>{if(!result.ok)throw new Error(result.error||'聊天操作失败');return result.data as T;});}
function translationApi<T>(action:string,payload?:unknown){const api=(window as WorkbenchBridgeWindow).manualReplyTranslation||workbenchHost().manualReplyTranslation;if(!api)return Promise.reject(new Error('翻译服务未就绪'));return api.request({action,payload}).then(result=>{if(!result.ok)throw new Error(result.error||'翻译失败');return result.data as T;});}

