 const translated=new Map<string,string>(),translating=new Set<string>(),imageTextResults=new Map<string,string>(),imageTextLoading=new Set<string>(),mediaLoading=new Set<string>(),mediaAttempted=new Set<string>(),mediaFailures=new Map<string,string>(),brokenImageIds=new Set<string>(),mediaForce=new Set<string>();let translationGeneration=0,mediaObserver:IntersectionObserver|undefined,translationViewportTimer:ReturnType<typeof setTimeout>|undefined,translationSyncing=false,mediaPending:string[]=[],mediaActiveCount=0,mediaGeneration=0,imageLightbox:HTMLDialogElement|undefined;
